import { chromium } from 'playwright';
import { fileURLToPath } from 'url';
import path from 'path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const htmlPath = path.join(__dirname, 'global-economic-prospects-infographic.html');
const outputPath = path.join(__dirname, 'final_poster.png');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();

// A1 at 150 DPI: 594mm x 841mm = 3508 x 4967 pixels
await page.setViewportSize({ width: 3508, height: 4967 });

await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });
await page.waitForTimeout(2000); // Wait for fonts and layout

// Remove the export button before screenshot
await page.evaluate(() => {
  const btn = document.querySelector('button');
  if (btn) btn.remove();
});

await page.screenshot({
  path: outputPath,
  type: 'png',
  fullPage: false,
  clip: { x: 0, y: 0, width: 3508, height: 4967 }
});

console.log(`Poster saved to: ${outputPath}`);
await browser.close();

