359	<script>
360	// Export button for PNG/SVG conversion
361	document.addEventListener('DOMContentLoaded', function() {
362	  const btn = document.createElement('button');
363	  btn.textContent = 'Export PNG';
364	  btn.style.cssText = 'position:fixed;top:10px;right:10px;z-index:9999;padding:10px 20px;background:#0050a0;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:14px;';
365	  btn.onclick = function() {
366	    // Use canvas-based approach for PNG export
367	    const poster = document.getElementById('poster');
368	    const svgData = '<svg xmlns="http://www.w3.org/2000/svg" width="' + poster.offsetWidth + '" height="' + poster.offsetHeight + '">' +
369	      '<foreignObject width="100%" height="100%">' +
370	      '<div xmlns="http://www.w3.org/1999/xhtml">' + poster.outerHTML + '</div>' +
371	      '</foreignObject></svg>';
372	    const blob = new Blob([svgData], {type: 'image/svg+xml'});
373	    const url = URL.createObjectURL(blob);
374	    const img = new Image();
375	    img.onload = function() {
376	      const canvas = document.createElement('canvas');
377	      canvas.width = poster.offsetWidth * 2;
378	      canvas.height = poster.offsetHeight * 2;
379	      const ctx = canvas.getContext('2d');
380	      ctx.scale(2, 2);
381	      ctx.drawImage(img, 0, 0);
382	      const link = document.createElement('a');
383	      link.download = 'final_poster.png';
384	      link.href = canvas.toDataURL('image/png');
385	      link.click();
386	      URL.revokeObjectURL(url);
387	    };
388	    img.src = url;
389	  };
390	  document.body.appendChild(btn);
391	});
392	</script>
393	</body>
