<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Global Economic Prospects - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body { width: 100%; height: 100%; overflow: hidden; background: #fff; }
    #container { width: 100%; height: 100%; }
  </style>
</head>
<body>
<div id="container"></div>
<script src="/app/vendor/infographic.min.js"></script>
<script>
  const infographic = new AntVInfographic.Infographic({
    container: '#container',
    width: '100%',
    height: '100%',
  });

  const syntax = `infographic list-zigzag-down-compact-card
data
  title Global Economic Prospects
  desc Resilience Amid Uncertainty — Strongest recovery in six decades, but vulnerable economies lag behind as trade tensions and policy uncertainty cloud the outlook.
  lists
    - label Strongest Recovery in 6 Decades
      value Post-2020 recovery unmatched in 60 years
      desc Advanced economies rebounded strongly. But EMDEs lag — the development gap is widening as global growth edges downward amid tariff effects and inventory drawdowns.
      icon chart line
    - label Risks to the Outlook
      value Trade Tensions & Tariffs
      desc Escalating tariffs disrupt supply chains and dampen investment. Financial volatility tightens EMDE financing. Inventory correction reduces near-term demand. Climate shocks threaten vulnerable regions.
      icon exclamation triangle
    - label Policy Actions for Sustained Growth
      value Global & Domestic Reform Agenda
      desc Trade: improve multilateral environment and diversify. Finance: ease EMDE constraints. Climate: scale mitigation and resilient infrastructure. Investment: catalyze private capital. Jobs: enhance skills and mobility.
      icon building columns
    - label World Bank 2030 Strategic Priorities
      value 1.2B youth entering working age
      desc Health: 1.5B people. Electricity: 300M in Sub-Saharan Africa. Agriculture: 300M farmers. Women's capital: 80M. Water security: 1B+ people (400M WBG commitment).
      icon globe
    - label Research Themes in Recent Issues
      value Evidence-Based Policy Analysis
      desc Fiscal policy and rules. Trade costs and global value chains. Commodity price cycles. Financial spillovers. Pandemic economics and income inequality. Small states fiscal challenges.
      icon book open
theme
  palette #002244 #0050a0 #0096a0 #0ea5e9 #f2a900
  base
    text
      font-family Helvetica Neue, Arial, sans-serif`;

  infographic.render(syntax);
  document.fonts?.ready.then(() => {
    infographic.render(syntax);
  }).catch((error) => console.error('Error:', error));

  // Add export button
  const btn = document.createElement('button');
  btn.textContent = 'Export SVG';
  btn.style.cssText = 'position:fixed;top:10px;right:10px;z-index:9999;padding:10px 20px;background:#0050a0;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:14px;';
  btn.onclick = async function() {
    try {
      const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
      const link = document.createElement('a');
      link.download = 'global-economic-prospects.svg';
      link.href = svgDataUrl;
      link.click();
    } catch(e) {
      console.error('Export failed:', e);
    }
  };
  document.body.appendChild(btn);
</script>
</body>
</html>
